using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.IO;
using UnityEngine.Rendering;
internal class ProceduralNature {
 int seed=42, leaves=6000, tex=1024; string folder; System.Random rng; Material bark,leaf,metal,wood; 
 float R(float a,float b){return Mathf.Lerp(a,b,(float)rng.NextDouble());}
 Vector3 Unit(){float y=R(-1,1),a=R(0,6.283185f),r=Mathf.Sqrt(1-y*y);return new Vector3(r*Mathf.Cos(a),y,r*Mathf.Sin(a));}
 class Geo {public List<Vector3> v=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> t=new List<int>();public void Tri(int a,int b,int c){t.Add(a);t.Add(b);t.Add(c);} public int Add(Vector3 p,Vector2 u){v.Add(p);uv.Add(u);return v.Count-1;}}
 void Tube(Geo g,Vector3 a,Vector3 b,float ra,float rb,int sides,int rings,float bend){Vector3 d=(b-a).normalized;Vector3 x=Vector3.Cross(d,Mathf.Abs(d.y)>.9f?Vector3.right:Vector3.up).normalized;Vector3 z=Vector3.Cross(d,x);int k=g.v.Count;for(int j=0;j<=rings;j++){float f=j/(float)rings;Vector3 p=Vector3.Lerp(a,b,f)+x*Mathf.Sin(f*Mathf.PI)*bend;for(int i=0;i<=sides;i++){float u=i/(float)sides,ang=u*Mathf.PI*2;float radius=Mathf.Lerp(ra,rb,f)*(1+.10f*Mathf.Sin(ang*5+f*4)+.05f*Mathf.Cos(ang*9));g.Add(p+(x*Mathf.Cos(ang)+z*Mathf.Sin(ang))*radius,new Vector2(u*2,f*Vector3.Distance(a,b)));}}for(int j=0;j<rings;j++)for(int i=0;i<sides;i++){int q=k+j*(sides+1)+i;g.Tri(q,q+1,q+sides+1);g.Tri(q+1,q+sides+2,q+sides+1);} }
 void Leaf(Geo g,Vector3 p,float size){Vector3 d=Unit(),x=Vector3.Cross(d,Unit()).normalized;if(x.sqrMagnitude<.1f)x=Vector3.Cross(d,Vector3.up).normalized;Vector3 n=Vector3.Cross(x,d);int k=g.v.Count;for(int j=0;j<=4;j++){float f=j/4f,w=Mathf.Sin(f*Mathf.PI)*size*.33f;Vector3 c=p+d*size*f+n*Mathf.Sin(f*Mathf.PI)*size*.12f;g.Add(c-x*w,new Vector2(0,f));g.Add(c+n*w*.22f,new Vector2(.5f,f));g.Add(c+x*w,new Vector2(1,f));}for(int j=0;j<4;j++)for(int i=0;i<2;i++){int q=k+j*3+i;g.Tri(q,q+3,q+1);g.Tri(q+1,q+3,q+4);}int back=g.v.Count;for(int i=0;i<15;i++)g.Add(g.v[k+i],g.uv[k+i]);for(int j=0;j<4;j++)for(int i=0;i<2;i++){int q=back+j*3+i;g.Tri(q,q+1,q+3);g.Tri(q+1,q+4,q+3);}}
 MeshRenderer SaveGeo(Geo g,Transform parent,string name,Material m){Mesh mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(g.v);mesh.SetUVs(0,g.uv);mesh.SetTriangles(g.t,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/"+name+".asset");var o=new GameObject(name);o.transform.SetParent(parent,false);o.AddComponent<MeshFilter>().sharedMesh=mesh;var r=o.AddComponent<MeshRenderer>();r.sharedMaterial=m;return r;}
 Texture2D Map(string name,Color[] pixels,bool linear,bool normal=false){var t=new Texture2D(tex,tex,TextureFormat.RGBA32,false,linear);t.SetPixels(pixels);t.Apply();string path=folder+"/"+name+".png";File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.sRGBTexture=!linear;imp.wrapMode=TextureWrapMode.Repeat;imp.maxTextureSize=tex;if(normal)imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 Material Surface(string name,Color baseColor,int type){int n=tex*tex;var h=new float[n];var a=new Color[n];var norm=new Color[n];var rough=new Color[n];var ao=new Color[n];var pack=new Color[n];var height=new Color[n];for(int y=0;y<tex;y++)for(int x=0;x<tex;x++){float u=x/(float)tex,v=y/(float)tex;float noise=Mathf.PerlinNoise(u*32,v*32);float f=type==0? .5f+.35f*Mathf.Sin(u*150+Mathf.PerlinNoise(u*12,v*5)*6)+noise*.15f:type==1?.55f+.2f*Mathf.Sin((u-.5f)*45+Mathf.Abs(v-.5f)*55)+noise*.2f:noise;h[y*tex+x]=Mathf.Clamp01(f);}for(int y=0;y<tex;y++)for(int x=0;x<tex;x++){int i=y*tex+x;float f=h[i],r=type==1?.48f:type==2?.6f:.86f;float oc=Mathf.Lerp(.58f,1,f);a[i]=baseColor*Mathf.Lerp(.55f,1.35f,f);a[i].a=1;rough[i]=new Color(r,r,r,1);ao[i]=new Color(oc,oc,oc,1);height[i]=new Color(f,f,f,1);pack[i]=new Color(type==2?.45f:0,0,0,1-r);Vector3 nn=new Vector3((h[y*tex+(x+tex-1)%tex]-h[y*tex+(x+1)%tex])*3,(h[((y+tex-1)%tex)*tex+x]-h[((y+1)%tex)*tex+x])*3,1).normalized;norm[i]=new Color(nn.x*.5f+.5f,nn.y*.5f+.5f,nn.z*.5f+.5f,1);}var sh=Shader.Find("Universal Render Pipeline/Lit");if(!sh)sh=Shader.Find("Standard");var m=new Material(sh);var al=Map(name+"_Albedo",a,false);var nm=Map(name+"_Normal",norm,true,true);var pk=Map(name+"_MetallicSmoothness",pack,true);var ocmap=Map(name+"_AO",ao,true);Map(name+"_Roughness",rough,true);Map(name+"_Height",height,true);m.SetTexture(m.HasProperty("_BaseMap")?"_BaseMap":"_MainTex",al);m.SetTexture("_BumpMap",nm);m.SetTexture("_MetallicGlossMap",pk);m.SetTexture("_OcclusionMap",ocmap);m.SetFloat("_Smoothness",1);m.SetFloat("_GlossMapScale",1);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");m.EnableKeyword("_METALLICGLOSSMAP");m.EnableKeyword("_OCCLUSIONMAP");m.enableInstancing=true;AssetDatabase.CreateAsset(m,folder+"/"+name+".mat");return m;}
 GameObject Tree(){var root=new GameObject("RoadsideTree");var lods=new LOD[3];for(int l=0;l<3;l++){rng=new System.Random(seed);var b=new Geo();var f=new Geo();int sides=24>>l;Tube(b,Vector3.zero,new Vector3(.25f,4.5f,0),.43f,.16f,sides,24>>l,.15f);var tips=new List<Vector3>();for(int i=0;i<12;i++){float ang=i*2.39996f;Vector3 radial=new Vector3(Mathf.Cos(ang),0,Mathf.Sin(ang));Vector3 start=new Vector3(.1f,2.3f+i*.19f,0);Vector3 end=start+radial*R(1.6f,3.4f)+Vector3.up*R(1.8f,3.3f);Tube(b,start,end,.13f,.035f,sides,12>>l,.23f);for(int j=0;j<6;j++){Vector3 s=Vector3.Lerp(start,end,.35f+j*.12f);Vector3 e=s+radial*R(.3f,1.1f)+Unit()*.8f+Vector3.up*R(.4f,1.3f);Tube(b,s,e,.04f,.008f,Mathf.Max(4,sides/2),Mathf.Max(2,8>>l),.09f);tips.Add(e);}}for(int i=0;i<10;i++){float ang=i*.6283f;Vector3 d=new Vector3(Mathf.Cos(ang),0,Mathf.Sin(ang));Tube(b,Vector3.up*.25f,d*R(1.3f,2.5f)-Vector3.up*.3f,.17f,.018f,sides,12>>l,.15f);for(int j=0;j<3;j++)Tube(b,d*(.6f+j*.35f),d*(1.5f+j*.4f)+new Vector3(-d.z,-.45f,d.x)*R(-.8f,.8f),.045f,.004f,Mathf.Max(4,sides/2),4,.1f);}int count=leaves/(l==0?1:l==1?4:12);for(int i=0;i<count;i++)Leaf(f,tips[i%tips.Count]+Unit()*R(.05f,.85f),R(.13f,.29f));var br=SaveGeo(b,root.transform,"TreeWood_LOD"+l,bark);var fr=SaveGeo(f,root.transform,"TreeLeaves_LOD"+l,leaf);lods[l]=new LOD(l==0?.42f:l==1?.16f:.025f,new Renderer[]{br,fr});Debug.Log("Tree LOD"+l+" triangles: "+(b.t.Count+f.t.Count)/3);}var group=root.AddComponent<LODGroup>();group.SetLODs(lods);group.RecalculateBounds();var col=root.AddComponent<CapsuleCollider>();col.center=Vector3.up*2;col.height=4;col.radius=.4f;var prefab=PrefabUtility.SaveAsPrefabAsset(root,folder+"/RoadsideTree.prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}

 GameObject Rock(int index){var o=new GameObject("WeatheredRock");var g=new Geo();int rings=18,sides=32;float sx=R(.45f,1.1f),sy=R(.35f,.8f),sz=R(.45f,1.2f);float offset=R(0,100);for(int j=0;j<=rings;j++){float v=j/(float)rings,phi=v*Mathf.PI;for(int i=0;i<=sides;i++){float u=i/(float)sides,a=u*2*Mathf.PI;Vector3 d=new Vector3(Mathf.Sin(phi)*Mathf.Cos(a),Mathf.Cos(phi),Mathf.Sin(phi)*Mathf.Sin(a));float n=1+.23f*(Mathf.PerlinNoise(d.x*3+offset,d.z*3+d.y*2+offset)-.5f)+.12f*Mathf.Sin(d.x*8+d.y*4+d.z*6);g.Add(new Vector3(d.x*sx*n,d.y*sy*n+sy*.65f,d.z*sz*n),new Vector2(u,v));}}for(int j=0;j<rings;j++)for(int i=0;i<sides;i++){int q=j*(sides+1)+i;g.Tri(q,q+1,q+sides+1);g.Tri(q+1,q+sides+2,q+sides+1);}var r=SaveGeo(g,o.transform,"RockMesh",wood);var c=o.AddComponent<MeshCollider>();c.sharedMesh=r.GetComponent<MeshFilter>().sharedMesh;var prefab=PrefabUtility.SaveAsPrefabAsset(o,folder+"/Rock.prefab");UnityEngine.Object.DestroyImmediate(o);return prefab;}
 public static void Build(string root,int seed,int tex,int leaves,out GameObject[] trees,out GameObject[] rocks){var b=new ProceduralNature{seed=seed,tex=tex,leaves=leaves,folder=root};b.rng=new System.Random(seed);b.bark=b.Surface("Bark",new Color(.39f,.29f,.20f),0);b.leaf=b.Surface("Leaf",new Color(.34f,.49f,.13f),1);b.wood=b.Surface("Rock",new Color(.43f,.42f,.36f),3);trees=new GameObject[4];rocks=new GameObject[6];for(int i=0;i<trees.Length;i++){b.folder=root+"/Tree_"+i;AssetDatabase.CreateFolder(root,"Tree_"+i);b.seed=seed+i*137;trees[i]=b.Tree();}for(int i=0;i<rocks.Length;i++){b.folder=root+"/Rock_"+i;AssetDatabase.CreateFolder(root,"Rock_"+i);b.rng=new System.Random(seed+i*193);rocks[i]=b.Rock(i);}AssetDatabase.SaveAssets();}
}
